CREATE OR REPLACE FUNCTION public.get_group_dispatch_ready_instances() RETURNS TABLE(whatsapp_number_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE stale record; BEGIN FOR stale IN SELECT id,claim_token,attempts FROM group_campaign_block_dispatches WHERE status='sending' AND locked_until<now() ORDER BY id LIMIT 50 LOOP PERFORM finish_group_dispatch_job(stale.id,stale.claim_token,'failed',coalesce(stale.attempts,0),'Envio sem confirmação após interrupção; conferir histórico antes de reenviar',NULL); END LOOP; RETURN QUERY SELECT DISTINCT j.whatsapp_number_id FROM group_campaign_block_dispatches j WHERE j.status='pending' AND j.seq IS NOT NULL AND j.send_after<=now() AND (j.locked_until IS NULL OR j.locked_until<now()) AND j.whatsapp_number_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM group_campaign_block_dispatches x WHERE x.whatsapp_number_id=j.whatsapp_number_id AND x.status='sending'); END $$; REVOKE ALL ON FUNCTION public.get_group_dispatch_ready_instances() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.get_group_dispatch_ready_instances() TO service_role;